{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Ofloxacin, a zwitterionic fluoroquinolone with the same 3-carboxylic acid/4-keto/6-fluoro core and a basic C7 amine, is almost completely absorbed in humans (≈100% oral bioavailability), demonstrating that full ionization and low logD do not preclude high oral bioavailability in this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Trovafloxacin, which shares an amino-substituted cyclopropane-containing C7 bicyclic amine on a fluoroquinolone core, has a mean absolute oral bioavailability of 87.6% in healthy volunteers, directly supporting high F for the query's C7 motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Moxifloxacin, an N1-cyclopropyl fluoroquinolone with a C7 bicyclic amine, has an absolute oral bioavailability of 86–92% in healthy volunteers, supporting high F for the query's N1-fluorocyclopropyl and bicyclic amine features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Finafloxacin, an N1-cyclopropyl fluoroquinolone with a C7 fused bicyclic amine and a polar nitrile, shows oral bioavailability ranging from about 60% to essentially complete, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Norfloxacin, a more polar fluoroquinolone with a simple piperazine, has lower but still above-threshold oral bioavailability (about 35–70%), indicating that even the least absorbed close analogues do not fall below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: multiple high-transfer fluoroquinolone analogues with the same zwitterionic quinolone core and similar C7/N1 substituents show absolute oral bioavailability of 60–100%, all above the 20% threshold; the physicochemical low-permeability prior is overridden by direct class evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact query molecule.",
    "Transporter/efflux behavior specific to the C7 spirocyclopropyl-pyrrolidinyl substituent is unknown.",
    "Food effects and formulation-dependent absorption for this exact structure are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

